package web

import (
	"encoding/hex"
	"encoding/json"
	"net/http"
	"testing"

	"github.com/gravitational/license"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/gravitational/teleport/e/lib/licensefile"
	"github.com/gravitational/teleport/e/lib/web/ui"
)

func TestGetLicenseHasAnonymizationKey(t *testing.T) {
	licenseNoAnonymizationKey, err := hex.DecodeString(licensePEMWithoutAnonKey)
	require.NoError(t, err)

	s := newWebSuite(t)
	webPack := s.newAuthWebPack(t, "dashboard-user")

	originalLicense, err := license.ParseLicensePEM(licenseNoAnonymizationKey)
	require.NoError(t, err)

	s.testAuthServer.Auth().SetLicense(originalLicense)

	endpoint := webPack.clt.Endpoint("enterprise", "license")
	resp, err := webPack.clt.Get(s.ctx, endpoint, nil)
	require.NoError(t, err)

	assert.Equal(t, http.StatusOK, resp.Code())
	assert.Equal(t, "application/json", resp.Headers().Get("Content-Type"))

	var glr ui.GetLicenseResponse
	require.NoError(t, json.NewDecoder(resp.Reader()).Decode(&glr))
	assert.NotEmpty(t, glr.PEM)
	assert.NotEqual(t, licenseNoAnonymizationKey, glr.PEM)

	license, err := licensefile.FromPEM([]byte(glr.PEM))
	assert.NoError(t, err)
	assert.NotEmpty(t, license.License.GetAnonymizationKey())
}

// licensePEMWithoutAnonKey is a hex-encoded license
const licensePEMWithoutAnonKey = ``
